const locEscape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let wardRefreshTimer;
function stopWardRefresh(){if(wardRefreshTimer){clearInterval(wardRefreshTimer);wardRefreshTimer=null}}
function hospitalDirections(h){
 const guide=hospitalGuides[h.id]||{},query=guide.address?`${h.name} ${guide.address}`:`${h.region} ${h.city} ${h.name}`;
 return `<section id="hospitalDirections" class="card hospital-directions"><h2>찾아오는 길</h2><strong>${locEscape(h.name)}</strong><p>${guide.address?locEscape(guide.address):'지도에서 병원명과 지역을 확인한 뒤 길찾기를 선택하세요.'}</p><div class="actions"><a class="secondary" href="https://map.naver.com/p/search/${encodeURIComponent(query)}" target="_blank" rel="noopener noreferrer">네이버 지도 · 길찾기</a><a class="secondary" href="https://map.kakao.com/?q=${encodeURIComponent(query)}" target="_blank" rel="noopener noreferrer">카카오맵 · 길찾기</a>${guide.phone?`<a class="secondary" href="tel:${guide.phone}">병원 문의 ${guide.phone}</a>`:''}</div>${guide.addressSource?`<p><a href="${locEscape(guide.addressSource)}" target="_blank" rel="noopener noreferrer">주소 확인 자료</a></p>`:''}</section>`;
}
function hospitalLanding(id){
 const h=findFacility(id);if(!h){home();return}
 const requestPath=h.kind?'care-request':'request',back=h.kind==='요양병원'?'nursing':h.kind==='재활병원'?'rehab':'hospitals';
 const submitted=new URLSearchParams(location.hash.split('?')[1]||'').get('submitted');
 app.innerHTML=`<section class="hospital-home"><a class="back" href="#${back}">← 병원 목록</a><h1>${locEscape(h.name)}</h1>${submitted?`<p class="notice success" role="status">간병의뢰가 접수되었습니다. 의뢰번호 <strong>${locEscape(submitted)}</strong><br><strong>저장 완료 · 아래 상황판에서 의뢰번호를 확인하세요.</strong><br><a class="secondary" href="#board/${h.id}">상황판에서 확인 →</a></p>`:''}<nav class="hospital-home-actions" aria-label="병원 서비스"><a class="primary" href="#${requestPath}/${h.id}">환자·보호자 간병의뢰</a><button class="secondary" id="jumpToBoard">간병인 · 의뢰번호로 신청</button><button class="secondary" id="jumpToDirections">찾아오는 길</button><a class="secondary" href="#guide/${h.id}">질환별 안내</a></nav><section id="hospitalHomeBoard" class="ward-dashboard"><div class="board-heading"><div><h2>간병 의뢰 상황판</h2><p>의뢰번호를 클릭하면 해당 의뢰의 간병인 신청서가 열립니다.</p></div><button class="secondary" id="boardRefresh">새로고침</button></div><div id="boardContent" aria-live="polite">등록된 의뢰를 불러오는 중입니다…</div></section>${hospitalDirections(h)}</section>`;
 document.querySelector('#jumpToBoard').onclick=()=>document.querySelector('#hospitalHomeBoard').scrollIntoView({behavior:'smooth',block:'start'});
 document.querySelector('#jumpToDirections').onclick=()=>document.querySelector('#hospitalDirections').scrollIntoView({behavior:'smooth',block:'start'});
 mountWardBoard(h);
}
function careLocationFields(h){
 const buildings=wardBuildings[h?.id]||[];
 return `<fieldset class="ward-location"><legend>간병 위치 · 상황판에 표시</legend><p>환자 이름·연락처·진료내용은 상황판에 표시하지 않습니다.</p><div class="location-grid"><label>건물<input name="building" maxlength="40" list="careBuildings" value="${buildings.length===1?locEscape(buildings[0].name):''}" placeholder="예: 암병원" required><datalist id="careBuildings">${buildings.map(b=>`<option value="${locEscape(b.name)}">`).join('')}</datalist></label><label>층<input name="floor" maxlength="20" list="careFloors" placeholder="예: 3층" pattern="[0-9]{1,2}층" title="3층처럼 숫자와 층을 입력하세요" required><datalist id="careFloors">${[...new Set(buildings.flatMap(b=>b.floors))].map(f=>`<option value="${locEscape(f)}">`).join('')}</datalist></label><label>병실<input name="room" maxlength="30" placeholder="병실번호" required></label><label>침상 (선택)<input name="bed" maxlength="20" placeholder="예: 1번"></label></div></fieldset>`;
}
function wardBoard(id){
 const h=findFacility(id);if(!h){app.innerHTML='<section class="card"><h2>병원을 먼저 선택해 주세요.</h2><a href="#hospitals">전국 병원 보기</a></section>';return}
 app.innerHTML=`<section class="ward-dashboard"><a class="back" href="#${h.kind?'care-facility':'hospital'}/${h.id}">← 병원 첫 화면</a><div class="board-heading"><div><h1>${locEscape(h.name)} 병동 상황판</h1><p>의뢰번호를 눌러 간병인 신청서를 작성하세요.</p><a class="primary" href="#${h.kind?'care-request':'request'}/${h.id}">새 간병의뢰 작성</a></div><button class="secondary" id="boardRefresh">새로고침</button></div><div id="boardContent" aria-live="polite">등록된 의뢰를 불러오는 중입니다…</div>${hospitalDirections(h)}</section>`;
 mountWardBoard(h);
}
function renderWardJob(x,id){return `<article class="card board-job"><span class="badge">신청 가능</span><h3>${locEscape(x.building)} · ${locEscape(x.floor)} · ${locEscape(x.room)}</h3><p>침상: ${locEscape(x.bed||'미지정')}</p><p><strong>간병 시작 ${locEscape(x.date)} ${locEscape(x.time)}</strong> (한국 시간)</p><p><strong>간병 종료 ${x.endDate&&x.endTime?locEscape(x.endDate)+' '+locEscape(x.endTime):'미등록 · 담당자 확인 필요'}</strong></p><a class="job-reference" href="#caregiver-apply/${encodeURIComponent(id)}?job=${encodeURIComponent(x.reference)}" aria-label="의뢰번호 ${locEscape(x.reference)} 간병인 신청"><span>간병 의뢰번호 · 클릭하여 신청</span><strong>${locEscape(x.reference)} →</strong></a></article>`}
async function mountWardBoard(h){
 stopWardRefresh();const id=h.id,container=document.querySelector('#boardContent'),refreshButton=document.querySelector('#boardRefresh');
 let items=[],building='',floor='',room='',loading=false;
 const config=wardBuildings[id]||[],guide=hospitalGuides[id]||{},uniq=values=>[...new Set(values.filter(Boolean))];
 const draw=()=>{
  const rows=items.filter(x=>(!building||x.building===building)&&(!floor||x.floor===floor)&&(!room||x.room===room));
  const names=uniq([...config.map(b=>b.name),...items.map(x=>x.building)]),selectedBuilding=config.find(b=>b.name===building);
  const floors=uniq([...(selectedBuilding?.floors||[]),...items.filter(x=>x.building===building).map(x=>x.floor)]).sort((a,b)=>parseInt(a)-parseInt(b));
  const rooms=uniq(items.filter(x=>x.building===building&&x.floor===floor).map(x=>x.room));
  container.innerHTML=`<div class="board-summary"><strong>신청 가능한 의뢰 ${items.length}건</strong><span>등록 의뢰 기준 · 30초마다 갱신</span></div><nav class="board-crumbs" aria-label="상황판 경로"><button data-back="building">전체 의뢰 · 건물 선택</button>${building?`<span>›</span><button data-back="floor">${locEscape(building)}</button>`:''}${floor?`<span>›</span><button data-back="room">${locEscape(floor)}</button>`:''}${room?`<span>›</span><strong>${locEscape(room)}</strong>`:''}</nav><div class="board-jobs">${rows.length?rows.map(x=>renderWardJob(x,id)).join(''):'<div class="card empty">이 위치에 등록된 간병 의뢰가 없습니다. 의뢰가 접수되면 여기에 표시됩니다.</div>'}</div><section class="hospital-spaces"><h2>건축 공간 · 입원실 안내</h2>${!building?`<h3>건물 선택</h3><div class="board-grid">${names.map(n=>`<button class="board-tile" data-building="${locEscape(n)}"><strong>${locEscape(n)}</strong><span>등록 의뢰 ${items.filter(x=>x.building===n).length}건</span><b>층별 병동 보기 →</b></button>`).join('')}</div>${!names.length?'<p>확인된 층별 안내를 준비 중입니다. 의뢰에 등록된 건물·층·병실은 자동으로 표시됩니다.</p>':''}`:!floor?`<h3>${locEscape(building)} · 층 선택</h3><div class="board-grid">${floors.map(n=>`<button class="board-tile" data-floor="${locEscape(n)}"><strong>${locEscape(n)}</strong><span>${locEscape(selectedBuilding?.floorDescriptions?.[n]||'병동')}</span><span>등록 의뢰 ${items.filter(x=>x.building===building&&x.floor===n).length}건</span></button>`).join('')}</div>${!floors.length?'<p>확인된 입원병동 층별 안내가 없습니다.</p>':''}`:`<h3>${locEscape(building)} · ${locEscape(floor)} · ${locEscape(selectedBuilding?.floorDescriptions?.[floor]||'입원실')}</h3>${id==='hospital-5'&&/암/.test(building)&&floor==='8층'?'<section class="corridor-layout" aria-label="암병동 8층 병실 구성"><div><strong>왼쪽</strong><p>808호 맞은편: 6인실</p><p>그 외 6인실 · 7인실</p></div><span>중앙 복도</span><div><strong>오른쪽</strong><p>808호: 2인실</p></div></section><p>803호: 1인실 · 침상 1번</p>':''}<div class="board-grid">${rooms.map(n=>`<button class="board-tile" data-room="${locEscape(n)}" aria-pressed="${room===n}"><strong>${locEscape(n)}</strong><span>등록 의뢰 ${items.filter(x=>x.building===building&&x.floor===floor&&x.room===n).length}건</span></button>`).join('')}</div>${!rooms.length?'<p>이 층에 등록된 병실 의뢰가 없습니다. 실제 병실번호가 접수되면 표시됩니다.</p>':''}`}${guide.floorNote?`<details class="floor-sources"><summary>층별 안내 출처와 확인 범위</summary><p>${locEscape(guide.floorNote)}</p><a href="${locEscape(guide.floorSource)}" target="_blank" rel="noopener noreferrer">공개 안내 보기</a></details>`:''}</section><p class="notice">신청 후 담당자가 배정을 확인합니다. 병실 위치가 없는 이전 접수는 상황판에 표시되지 않습니다.</p><p id="boardUpdateStatus" role="status"></p>`;
  container.querySelectorAll('[data-building]').forEach(b=>b.onclick=()=>{building=b.dataset.building;floor=room='';draw()});
  container.querySelectorAll('[data-floor]').forEach(b=>b.onclick=()=>{floor=b.dataset.floor;room='';draw()});
  container.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{room=b.dataset.room;draw()});
  container.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>{if(b.dataset.back==='building')building=floor=room='';else if(b.dataset.back==='floor')floor=room='';else room='';draw()});
 };
 const refresh=async()=>{
  if(loading||!container.isConnected)return;loading=true;refreshButton.disabled=true;
  try{const response=await fetch('/api/board?hospitalId='+encodeURIComponent(id),{cache:'no-store'}),data=await response.json();if(!response.ok)throw Error(data.error||'상황판을 불러오지 못했습니다.');if(!container.isConnected)return;const next=data.items;const unchanged=container.querySelector('.board-summary')&&JSON.stringify(next)===JSON.stringify(items);items=next;if(!unchanged)draw();const status=container.querySelector('#boardUpdateStatus');if(status)status.textContent=''}catch(e){if(!container.isConnected)return;const status=container.querySelector('#boardUpdateStatus');if(status)status.textContent='갱신 실패: '+e.message;else container.innerHTML=`<p class="notice error">${locEscape(e.message)} 새로고침을 눌러 다시 시도해 주세요.</p>`}finally{loading=false;refreshButton.disabled=false}
 };
 refreshButton.onclick=refresh;
 await refresh();if(!container.isConnected)return;
 wardRefreshTimer=setInterval(()=>{if(!container.isConnected){stopWardRefresh();return}if(document.visibilityState==='visible')refresh()},30000);
}
